package mrpapermoon.whisper.meshimport android.content.Contextimport io.github.oshai.kotlinlogging.KotlinLoggingimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.ObsoleteCoroutinesApiimport kotlinx.coroutines.awaitCancellationimport kotlinx.coroutines.channels.actorimport kotlinx.coroutines.launchimport kotlinx.coroutines.plusimport kotlinx.coroutines.supervisorScopeimport mrpapermoon.whisper.mesh.db.RumorDatabaseimport mrpapermoon.whisper.mesh.nearby.EndpointConnectionHolderimport mrpapermoon.whisper.service.NearbyConnectionsAdapterimport java.util.concurrent.ConcurrentHashMapimport java.util.concurrent.atomic.AtomicBooleanimport javax.inject.Singletoninterface MeshNetworkManager {	@Throws(IllegalStateException::class)	suspend fun startService()}@Singleton@OptIn(ObsoleteCoroutinesApi::class)internal class MeshNetworkManagerImpl(	private val cipher: ByteArray,	private val context: Context,	private val database: RumorDatabase,	private val userName: String,	private val uuid: String,) : MeshNetworkManager {	private val logger = KotlinLogging.logger {}	private val isServiceStarted = AtomicBoolean(false)	override suspend fun startService() {		if (isServiceStarted.getAndSet(true)) throw IllegalStateException("Service already started")		supervisorScope {			val connectionsAdapter = NearbyConnectionsAdapter.getConnectionsAdapter(context, this + Dispatchers.IO, uuid)			val connectionsHolderMap = ConcurrentHashMap<String, EndpointConnectionHolder>()			launch(Dispatchers.Default) {				connectionsAdapter.collect { event ->					val endpointId = event.endpointId					val connectionHolder = connectionsHolderMap						.computeIfAbsent(endpointId) { _ ->							logger.debug { "New connection(endpointId: $endpointId, event :$event)" }							val actor = (this + Dispatchers.Unconfined).actor {								for (message in channel) {									connectionsAdapter.sendPayloadBytes(endpointId, message)								}							}							EndpointConnectionHolder(actor, userName = userName, userCipher = cipher, database = database, endpointId = endpointId)						}					runCatching {						connectionHolder.onEvent(event)					}						.onFailure {							if (it is EndpointConnectionHolder.ConnectionComplete) {								logger.debug { "On data sharing complete(endpointId: $endpointId)" }								connectionsHolderMap.remove(endpointId)							} else {								logger.error(it) { "On data sharing error" }								throw it							}						}				}			}			try {				awaitCancellation()			} finally {				connectionsHolderMap.clear()				isServiceStarted.set(false)			}		}	}}